package ec.edu.monster.servicios;
import ec.edu.monster.configuracion.ConfiguracionSoap; import ec.edu.monster.modelos.Modelos.*; import java.io.*; import java.math.BigDecimal; import java.net.*; import java.nio.charset.StandardCharsets; import java.util.*; import javax.xml.XMLConstants; import javax.xml.parsers.DocumentBuilderFactory; import org.w3c.dom.*;
/** Gateway SOAP reutilizable por los controladores de escritorio. */
public final class ClienteSoapEureka {
 private static final String NS="http://servicios.monster.edu.ec/";
 private String base(){return ConfiguracionSoap.baseUrl();}
 public Sesion login(String u,String p)throws Exception{Document d=call("LoginServicio/LoginControlador","login",null,"<usuario>"+e(u)+"</usuario><contrasenia>"+e(p)+"</contrasenia>");fault(d);Element r=one(d,"respuestaLogin");return new Sesion(t(r,"token"),t(r,"usuarioId"),t(r,"usuarioNombre"));}
 public void logout(String token)throws Exception{Document d=call("LoginServicio/LoginControlador","logout",null,"<token>"+e(token)+"</token>");fault(d);}
 public List<Cuenta> cuentas(String token)throws Exception{Document d=call("CuentaServicio/CuentaControlador","listarCuentas",token,"");fault(d);List<Cuenta> r=new ArrayList<>();for(Element x:many(d,"return"))r.add(new Cuenta(t(x,"cuentaId"),t(x,"cuentaNumero"),n(t(x,"cuentaSaldo")),t(x,"cuentaEstado"),t(x,"sucursalId")));return r;}
 public Map<String,String> disponibilidades(String token)throws Exception{Document d=call("CuentaServicio/CuentaControlador","listarDisponibilidades",token,"");fault(d);Map<String,String> r=new HashMap<>();for(Element x:many(d,"disponibilidad"))r.put(t(x,"cuentaId"),t(x,"estado"));return r;}
 public List<Cliente> clientesParaCuenta(String token)throws Exception{Document d=call("CuentaServicio/CuentaControlador","listarClientesParaCuenta",token,"");fault(d);List<Cliente> r=new ArrayList<>();for(Element x:many(d,"cliente"))r.add(new Cliente(t(x,"usuarioId"),t(x,"nombreCompleto"),t(x,"usuario")));return r;}
 public Cuenta crearCuentaParaUsuario(String token,String usuarioId)throws Exception{Document d=call("CuentaServicio/CuentaControlador","crearCuentaParaUsuario",token,"<usuarioId>"+e(usuarioId)+"</usuarioId>");fault(d);Element x=one(d,"cuenta");return new Cuenta(t(x,"cuentaId"),t(x,"cuentaNumero"),n(t(x,"cuentaSaldo")),t(x,"cuentaEstado"),t(x,"sucursalId"));}
 public List<Movimiento> movimientos(String token,String id)throws Exception{Document d=call("TransaccionServicio/TransaccionControlador","listarPorCuenta",token,"<cuentaId>"+e(id)+"</cuentaId>");fault(d);List<Movimiento> r=new ArrayList<>();for(Element x:many(d,"transacciones"))r.add(new Movimiento(t(x,"transaccionId"),t(x,"cuentaId"),n(t(x,"transaccionSaldo")),t(x,"transaccionTipo"),t(x,"transaccionCreadoEn")));return r;}
 public void transferir(String token,String o,String d,BigDecimal m)throws Exception{Document x=call("TransaccionServicio/TransaccionControlador","realizarTransferencia",token,"<cuentaOrigenId>"+e(o)+"</cuentaOrigenId><cuentaDestinoId>"+e(d)+"</cuentaDestinoId><monto>"+m.toPlainString()+"</monto>");fault(x);}
 public void movimiento(String token,String tipo,String id,BigDecimal m)throws Exception{Document x=call("TransaccionServicio/TransaccionControlador","generarTransaccion",token,"<tipo>"+e(tipo)+"</tipo><cuentaId>"+e(id)+"</cuentaId><monto>"+m.toPlainString()+"</monto>");fault(x);}
 public void reversar(String token,String id)throws Exception{Document x=call("TransaccionServicio/TransaccionControlador","reversarTransaccion",token,"<transaccionId>"+e(id)+"</transaccionId>");fault(x);}
 public Perfil perfil(String token,String uid)throws Exception{Document d=call("UsuarioServicio/UsuarioControlador","obtenerPerfilBancario",token,"<usuarioId>"+e(uid)+"</usuarioId>");fault(d);Element p=one(d,"perfil"),u=one(p,"usuario");List<Cuenta> cs=new ArrayList<>();for(Element x:many(p,"cuentas"))cs.add(new Cuenta(t(x,"cuentaId"),t(x,"cuentaNumero"),n(t(x,"cuentaSaldo")),t(x,"cuentaEstado"),t(x,"sucursalId")));return new Perfil(t(u,"usuarioNombre")+" "+t(u,"usuarioApellido"),t(u,"usuarioUsuario"),t(u,"usuarioTelefono"),cs);}
 private Document call(String service,String op,String token,String body)throws Exception{String h=token==null?"":"<ser:token>"+e(token)+"</ser:token>";String xml="<?xml version=\"1.0\"?><soap:Envelope xmlns:soap=\"http://schemas.xmlsoap.org/soap/envelope/\" xmlns:ser=\""+NS+"\"><soap:Header>"+h+"</soap:Header><soap:Body><ser:"+op+">"+body+"</ser:"+op+"></soap:Body></soap:Envelope>";HttpURLConnection c=(HttpURLConnection)new URL(base()+"/"+service).openConnection();c.setConnectTimeout(8000);c.setReadTimeout(20000);c.setRequestMethod("POST");c.setDoOutput(true);c.setRequestProperty("Content-Type","text/xml; charset=utf-8");try(OutputStream o=c.getOutputStream()){o.write(xml.getBytes(StandardCharsets.UTF_8));}InputStream i=c.getResponseCode()>=400?c.getErrorStream():c.getInputStream();DocumentBuilderFactory f=DocumentBuilderFactory.newInstance();f.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING,true);f.setAttribute(XMLConstants.ACCESS_EXTERNAL_DTD,"");f.setAttribute(XMLConstants.ACCESS_EXTERNAL_SCHEMA,"");f.setNamespaceAware(true);return f.newDocumentBuilder().parse(i);}
 private static void fault(Document d)throws Exception{NodeList x=d.getElementsByTagNameNS("*","faultstring");if(x.getLength()>0)throw new IllegalStateException(x.item(0).getTextContent());} private static Element one(Node n,String q){NodeList x=n instanceof Document?((Document)n).getElementsByTagNameNS("*",q):((Element)n).getElementsByTagNameNS("*",q);return x.getLength()==0?null:(Element)x.item(0);}private static List<Element> many(Node n,String q){NodeList x=n instanceof Document?((Document)n).getElementsByTagNameNS("*",q):((Element)n).getElementsByTagNameNS("*",q);List<Element> r=new ArrayList<>();for(int i=0;i<x.getLength();i++)r.add((Element)x.item(i));return r;}private static String t(Element e,String q){Element x=one(e,q);return x==null?"":x.getTextContent();}private static BigDecimal n(String x){try{return new BigDecimal(x);}catch(Exception e){return BigDecimal.ZERO;}}private static String e(String x){return x==null?"":x.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;");}
}
